Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The Utilization Report's parent.

=item * C<< $msg->utilization_report() >> / C<< $msg->utilization_report($value) >>

Type: C<Message> (L<Google::Cloud::Vmmigration::V1::Vmmigration::UtilizationReport>)

Required. The report to create.

=item * C<< $msg->utilization_report_id() >> / C<< $msg->utilization_report_id($value) >>

Type: C<String>

Required. The ID to use for the report, which will become the final
component of the reports's resource name.

This value maximum length is 63 characters, and valid characters
are /[a-z][0-9]-/. It must start with an english letter and must not
end with a hyphen.

=item * C<< $msg->request_id() >> / C<< $msg->request_id($value) >>

Type: C<String>

A request ID to identify requests. Specify a unique request ID
so that if you must retry your request, the server will know to ignore
the request if it has already been completed. The server will guarantee
that for at least 60 minutes since the first request.

For example, consider a situation where you make an initial request and
the request times out. If you make the request again with the same request
ID, the server can check if original operation with the same request ID
was received, and if so, will ignore the second request. This prevents
clients from accidentally creating duplicate commitments.

The request ID must be a valid UUID with the exception that zero UUID is
not supported (00000000-0000-0000-0000-000000000000).

=back

