Type: C<String>

The machine type series to create the VM with.

=item * C<< $msg->machine_type() >> / C<< $msg->machine_type($value) >>

Type: C<String>

The machine type to create the VM with.

=item * C<< $msg->network_tags() >> / C<< $msg->network_tags($value) >>

Type: C<String>

A list of network tags to associate with the VM.

=item * C<< $msg->network_interfaces() >> / C<< $msg->network_interfaces($value) >>

Type: C<Message> (L<Google::Cloud::Vmmigration::V1::Vmmigration::NetworkInterface>)

List of NICs connected to this VM.

=item * C<< $msg->service_account() >> / C<< $msg->service_account($value) >>

Type: C<String>

Optional. The service account to associate the VM with.

=item * C<< $msg->disk_type() >> / C<< $msg->disk_type($value) >>

Type: C<Enum> (L<Google::Cloud::Vmmigration::V1::ComputeEngineDiskType>)

The disk type to use in the VM.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Vmmigration::V1::Vmmigration::ComputeEngineTargetDefaults::LabelsEntry>)

A map of labels to associate with the VM.

=item * C<< $msg->license_type() >> / C<< $msg->license_type($value) >>

Type: C<Enum> (L<Google::Cloud::Vmmigration::V1::ComputeEngineLicenseType>)

The license type to use in OS adaptation.

=item * C<< $msg->applied_license() >> / C<< $msg->applied_license($value) >>

Type: C<Message> (L<Google::Cloud::Vmmigration::V1::Vmmigration::AppliedLicense>)

Output only. The OS license returned from the adaptation module report.

=item * C<< $msg->compute_scheduling() >> / C<< $msg->compute_scheduling($value) >>

Type: C<Message> (L<Google::Cloud::Vmmigration::V1::Vmmigration::ComputeScheduling>)

Compute instance scheduling information (if empty default is used).

=item * C<< $msg->secure_boot() >> / C<< $msg->secure_boot($value) >>

Type: C<Bool>

Defines whether the instance has Secure Boot enabled.
This can be set to true only if the VM boot option is EFI.

=item * C<< $msg->enable_vtpm() >> / C<< $msg->enable_vtpm($value) >>

Type: C<Bool>

Optional. Defines whether the instance has vTPM enabled.
This can be set to true only if the VM boot option is EFI.

=item * C<< $msg->enable_integrity_monitoring() >> / C<< $msg->enable_integrity_monitoring($value) >>

Type: C<Bool>

Optional. Defines whether the instance has integrity monitoring enabled.
This can be set to true only if the VM boot option is EFI, and vTPM is
enabled.

=item * C<< $msg->boot_option() >> / C<< $msg->boot_option($value) >>

Type: C<Enum> (L<Google::Cloud::Vmmigration::V1::ComputeEngineBootOption>)

Output only. The VM Boot Option, as set in the source VM.

=item * C<< $msg->metadata() >> / C<< $msg->metadata($value) >>

Type: C<Message> (L<Google::Cloud::Vmmigration::V1::Vmmigration::ComputeEngineTargetDefaults::MetadataEntry>)

The metadata key/value pairs to assign to the VM.

=item * C<< $msg->additional_licenses() >> / C<< $msg->additional_licenses($value) >>

Type: C<String>

Additional licenses to assign to the VM.

=item * C<< $msg->hostname() >> / C<< $msg->hostname($value) >>

Type: C<String>

The hostname to assign to the VM.

=item * C<< $msg->encryption() >> / C<< $msg->encryption($value) >>

Type: C<Message> (L<Google::Cloud::Vmmigration::V1::Vmmigration::Encryption>)

Optional. Immutable. The encryption to apply to the VM disks.

=item * C<< $msg->boot_conversion() >> / C<< $msg->boot_conversion($value) >>

Type: C<Enum> (L<Google::Cloud::Vmmigration::V1::BootConversion>)

Optional. By default the virtual machine will keep its existing boot
option. Setting this property will trigger an internal process which will
convert the virtual machine from using the existing boot option to another.

=item * C<< $msg->adaptation_modifiers() >> / C<< $msg->adaptation_modifiers($value) >>

Type: C<Message> (L<Google::Cloud::Vmmigration::V1::Vmmigration::AdaptationModifier>)

Optional. AdaptationModifiers are the set of modifiers used during OS
adaptation.

=item * C<< $msg->disk_replica_zones() >> / C<< $msg->disk_replica_zones($value) >>

Type: C<String>

Optional. Additional replica zones of the target regional disks.
If this list is not empty a regional disk will be created. The first
supported zone would be the one stated in the
[zone][google.cloud.vmmigration.v1.ComputeEngineTargetDefaults.zone] field.
The rest are taken from this list. Please refer to the [regional disk
creation
API](https://cloud.google.com/compute/docs/regions-zones/global-regional-zonal-resources)
for further details about regional vs zonal disks. If not specified, a
zonal disk will be created in the same zone the VM is created.

=item * C<< $msg->storage_pool() >> / C<< $msg->storage_pool($value) >>

Type: C<String>

Optional. If specified this will be the storage pool in which the disk is
created. This is the full path of the storage pool resource, for example:
"projects/my-project/zones/us-central1-a/storagePools/my-storage-pool".
The storage pool must be in the same project and zone as the target disks.
The storage pool's type must match the disk type.

=back

