=head2 Google::Cloud::Vmmigration::V1::Vmmigration::ComputeScheduling

Scheduling information for VM on maintenance/restart behaviour and
node allocation in sole tenant nodes.
Options for instance behavior when the host machine undergoes
maintenance that may temporarily impact instance performance.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->on_host_maintenance() >> / C<< $msg->on_host_maintenance($value) >>

Type: C<Enum> (L<Google::Cloud::Vmmigration::V1::ComputeScheduling::OnHostMaintenance>)

How the instance should behave when the host machine undergoes
maintenance that may temporarily impact instance performance.

=item * C<< $msg->restart_type() >> / C<< $msg->restart_type($value) >>

Type: C<Enum> (L<Google::Cloud::Vmmigration::V1::ComputeScheduling::RestartType>)

Whether the Instance should be automatically restarted whenever it is
terminated by Compute Engine (not terminated by user).
This configuration is identical to `automaticRestart` field in Compute
Engine create instance under scheduling.
It was changed to an enum (instead of a boolean) to match the default
value in Compute Engine which is automatic restart.

=item * C<< $msg->node_affinities() >> / C<< $msg->node_affinities($value) >>

Type: C<Message> (L<Google::Cloud::Vmmigration::V1::Vmmigration::SchedulingNodeAffinity>)

A set of node affinity and anti-affinity configurations for sole tenant
nodes.

=item * C<< $msg->min_node_cpus() >> / C<< $msg->min_node_cpus($value) >>

Type: C<Int32>

The minimum number of virtual CPUs this instance will consume when
running on a sole-tenant node. Ignored if no node_affinites are
configured.

